<script setup>
import { computed, ref, watch } from 'vue'
import Icon from '../components/Icon.vue'
import MetricCard from '../components/MetricCard.vue'
import StatusBadge from '../components/StatusBadge.vue'
import EnvironmentCard from '../components/EnvironmentCard.vue'
import ResourceBars from '../components/ResourceBars.vue'
const props = defineProps({ envs: Array, snapshot: Object })
const emit = defineEmits(['details', 'borrow', 'run', 'lease', 'navigate', 'maintenance', 'create'])
const tab = ref('all'), arch = ref('all'), type = ref('all'), query = ref(''), view = ref('grid'), page = ref(1)
const occupiedStates = ['running', 'leased']
const counts = computed(() => ({ all: props.envs.length, available: props.envs.filter(e => e.status === 'available').length, occupied: props.envs.filter(e => occupiedStates.includes(e.status)).length, unavailable: props.envs.filter(e => !['available', ...occupiedStates].includes(e.status)).length }))
const tabs = [{ id: 'all', label: '全部环境' }, { id: 'available', label: '可借用' }, { id: 'occupied', label: '使用中' }, { id: 'unavailable', label: '维护 / 隔离' }]
const filtered = computed(() => props.envs.filter(e => (tab.value === 'all' || (tab.value === 'occupied' ? occupiedStates.includes(e.status) : tab.value === 'unavailable' ? !['available', ...occupiedStates].includes(e.status) : e.status === tab.value)) && (arch.value === 'all' || arch.value === e.arch) && (type.value === 'all' || type.value === e.type) && `${e.id} ${e.name} ${e.description}`.toLowerCase().includes(query.value.trim().toLowerCase())))
const pages = computed(() => Math.max(1, Math.ceil(filtered.value.length / 4)))
const paginated = computed(() => filtered.value.slice((page.value - 1) * 4, page.value * 4))
watch([tab, arch, type, query], () => { page.value = 1 })
watch(pages, count => { page.value = Math.min(page.value, count) })
const attention = computed(() => [
  { count: props.snapshot.leases.filter(l => l.status === 'checking').length, title: '个借用待健康复核', icon: 'shield', tone: 'amber', target: 'leases' },
  { count: props.snapshot.runs.filter(r => r.status === 'reconciling').length, title: '个任务待对账', icon: 'clipboard', tone: 'amber', target: 'runs' },
  { count: props.snapshot.maintenance.filter(m => m.status === 'isolated').length, title: '个设备组已隔离', icon: 'alert', tone: 'red', target: 'maintenance' },
].filter(item => item.count))
function clear() { tab.value = 'all'; arch.value = 'all'; type.value = 'all'; query.value = '' }
</script>
<template>
  <div class="page-heading"><div><div class="eyebrow">RESOURCE WORKSPACE</div><h1>环境资源中心<span class="demo-tag">演示数据</span></h1><p>统一管理测试环境，让每一次执行都有据可循。</p></div><div class="heading-actions"><button class="button secondary" @click="emit('create')"><Icon name="plus" :size="17" />新增环境</button><button class="button secondary" @click="emit('navigate', 'leases')"><Icon name="clipboard" :size="17" />我的借用</button><button class="button primary" @click="emit('borrow')"><Icon name="plus" :size="18" />申请环境</button></div></div>
  <div class="metrics-grid environment-metrics"><MetricCard label="环境总数" :value="counts.all" detail="跨架构 · 统一资源视图" icon="server" spark /><MetricCard label="可借用" :value="counts.available" detail="全部关联设备均可用" icon="box" tone="green" spark /><MetricCard label="使用中" :value="counts.occupied" detail="人工借用与自动任务" icon="play" spark /><MetricCard label="维护 / 隔离" :value="counts.unavailable" detail="含待对账、清理与复核" icon="tool" tone="amber" spark /></div>
  <div class="environment-layout"><div class="environment-main"><section class="panel environment-browser" aria-label="环境列表">
    <div class="environment-toolbar"><div class="tabs" role="tablist" aria-label="环境状态"><button v-for="item in tabs" :key="item.id" role="tab" :aria-selected="tab === item.id" :class="{ active: tab === item.id }" @click="tab = item.id">{{ item.label }}<span>{{ counts[item.id] }}</span></button></div><div class="view-toggle" aria-label="视图切换"><button class="icon-button" :class="{ selected: view === 'grid' }" :aria-pressed="view === 'grid'" aria-label="卡片视图" @click="view = 'grid'"><Icon name="grid" :size="17" /></button><button class="icon-button" :class="{ selected: view === 'list' }" :aria-pressed="view === 'list'" aria-label="列表视图" @click="view = 'list'"><Icon name="list" :size="18" /></button></div></div>
    <div class="filter-bar"><label class="search-field"><Icon name="search" :size="17" /><input v-model="query" aria-label="搜索环境" placeholder="搜索环境名称或 ID" /><button v-if="query" class="icon-button" aria-label="清空环境搜索" @click="query = ''"><Icon name="close" :size="14" /></button></label><label class="select-label">架构<select v-model="arch" aria-label="筛选架构"><option value="all">全部架构</option><option>ARM64</option><option>x86_64</option></select></label><label class="select-label">类型<select v-model="type" aria-label="筛选类型"><option value="all">全部类型</option><option value="physical">物理机</option><option value="virtual">虚拟机</option></select></label></div>
    <div v-if="filtered.length && view === 'grid'" class="environment-grid"><EnvironmentCard v-for="env in paginated" :key="env.id" :env="env" @details="emit('details', $event)" @borrow="emit('borrow', $event)" @run="emit('run', $event)" @lease="emit('lease', $event)" @maintenance="emit('maintenance', $event)" /></div>
    <div v-else-if="filtered.length" class="table-scroll environment-list"><table class="data-table"><thead><tr><th>环境 / ID</th><th>架构 / 类型</th><th>设备</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="env in paginated" :key="env.id"><td><button class="plain-title" @click="emit('details', env)">{{ env.name }}</button><small class="mono">{{ env.id }}</small></td><td>{{ env.arch }}<small>{{ env.type === 'physical' ? '物理机' : '虚拟机' }}</small></td><td>{{ env.deviceIds.length }} 台</td><td><StatusBadge :status="env.status" /></td><td><button class="text-button" @click="env.status === 'available' ? emit('borrow', env) : emit('details', env)">{{ env.status === 'available' ? '申请借用' : '查看详情' }}</button></td></tr></tbody></table></div>
    <div v-else class="empty-state"><Icon name="search" :size="38" /><h3>没有找到匹配的环境</h3><p>调整搜索词或筛选条件，看看其他资源。</p><button class="button secondary small" @click="clear">清空筛选</button></div>
    <div class="pagination"><span>共 {{ filtered.length }} 个环境 · 每页 4 个</span><div><button class="icon-button" aria-label="上一页" :disabled="page <= 1" @click="page--"><Icon name="chevron" :size="16" class="rotate" /></button><button v-for="n in pages" :key="n" class="page-button" :class="{ active: page === n }" :aria-label="`第 ${n} 页`" :aria-current="page === n ? 'page' : undefined" @click="page = n">{{ n }}</button><button class="icon-button" aria-label="下一页" :disabled="page >= pages" @click="page++"><Icon name="chevron" :size="16" /></button></div></div>
  </section><section class="panel execution-strip"><span><Icon name="flow" />当前执行</span><button @click="emit('navigate', 'runs')">执行中<strong>{{ snapshot.runs.filter(r => r.status === 'running').length }}</strong><i class="dot blue" /></button><button @click="emit('navigate', 'runs')">待清理<strong>{{ snapshot.runs.filter(r => r.status === 'cleaning').length }}</strong><i class="dot amber" /></button><button class="text-button" @click="emit('navigate', 'runs')">执行记录<Icon name="arrow" :size="16" /></button></section></div>
    <aside class="right-rail"><section class="panel rail-panel"><div class="panel-heading"><h2>设备占用分布</h2><Icon name="chart" :size="17" /></div><ResourceBars :devices="snapshot.devices" /><div class="subtle-note">按唯一设备统计，共 {{ snapshot.devices.length }} 台</div></section>
      <section class="panel rail-panel"><div class="panel-heading"><h2>待处理事项</h2><span class="count-pill">{{ attention.reduce((s, i) => s + i.count, 0) }}</span></div><button v-for="item in attention" :key="item.title" class="attention-item" @click="emit('navigate', item.target)"><span class="soft-icon" :class="`tone-${item.tone}`"><Icon :name="item.icon" :size="19" /></span><span><strong :class="`color-${item.tone}`">{{ item.count }}</strong> {{ item.title }}</span><Icon name="chevron" :size="16" /></button><p v-if="!attention.length" class="subtle-note">暂无待处理事项</p><div class="resource-rule"><Icon name="lock" :size="17" /><div><strong>共享设备独占锁定</strong><p>同一台设备同一时间仅允许一项占用。</p></div></div></section>
      <section class="panel rail-panel"><div class="panel-heading"><h2>最近动态</h2><span class="live-label">MOCK</span></div><ol class="activity-list"><li v-for="(item, i) in snapshot.activities.slice(0, 4)" :key="i"><i class="dot" :class="item.tone" /><span class="mono">{{ item.time }}</span><p>{{ item.text }}</p></li></ol></section>
    </aside>
  </div>
</template>
